import * as model from './domain.mjs';
import {metrics,compare} from '../measurement/metrics.mjs';
import {label,reasonOptions,reviewFields,ackScenario,outcomeOptions,sponsorshipMarkup,funnelMarkup,certificateMarkup} from './ui.mjs';
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=model.createSession(),page='join',currentId=null,editingId=null,queueId=null,modalOpen=false,connectionError=false,snapshot=null;
const qCurrent=()=>state.questions.find(q=>q.question_id===currentId);
const ackScenarios=new Map();
const format=value=>value===null?'N/A':`${Number(value.toFixed(2))}%`;
const sectionOptions=selected=>'<option value="">Select a disclosure reference</option>'+model.SECTIONS.map(s=>`<option value="${s.id}" ${selected===s.id?'selected':''}>${s.id} · ${s.title}</option>`).join('');
function ackLabel(q){if(q.acknowledgement==='success')return 'Successful demo acknowledgement · no real transaction';if(q.acknowledgement==='failed')return q.wallet_decision==='off_chain'?'Final off-chain decision after failed demo attempt':'Demo acknowledgement failed · question saved';if(q.acknowledgement==='skipped')return 'Off-chain · no blockchain transaction required';return 'Question saved · optional acknowledgement pending';}
function preview(q){return `<div class="question-preview">${esc(q.text.length>160?q.text.slice(0,160)+'…':q.text)}</div>${q.text.length>160?`<details><summary>Show full question</summary><div class="full-question">${esc(q.text)}</div></details>`:''}`;}
function certificateButtons(questions){return questions.filter(q=>q.acknowledgement==='success').map(q=>`<button class="button text-action" data-action="certificate" data-id="${q.question_id}">Example participation certificate · ${q.question_id} v${q.version}</button>`).join('');}
const panel=body=>`<article class="panel">${body}</article>`;
function notify(message){$('#notice').textContent=message;}
function notebook(){const p=model.participant(state),m=metrics(state,{includeQA:true});$('#identity').textContent=p?`${p.persona_label} · ${p.canonical_participant_id}`:'No fixture selected';const values=[['Registered canonical people',new Set(state.registrations.map(r=>r.canonical_participant_id)).size],['Invitation',p?p.invitation_status:'Not selected'],['KYC (synthetic)',p?p.kyc_demo_status:'Not selected'],['Wallet (demo)',p&&state.wallet_connections.includes(p.canonical_participant_id)?'Connected':'Disconnected'],['Eligible disclosure viewers',m.disclosure_viewers],['Accepted / qualified questions',`${m.accepted_questions} / ${m.qualified_questions}`],['Qualified people',m.qualified_participants],['Live QA conversion (tiny synthetic sample)',format(m.qualified_conversion)],['Demo attempts / real TXs',`${m.ack_attempts} / ${m.real_transactions}`],['Explicit abandonments',state.events.filter(e=>e.event_type==='disclosure_abandoned').length]];$('#facts').innerHTML=values.map(([a,b])=>`<div><dt>${esc(a)}</dt><dd>${esc(b)}</dd></div>`).join('');$('#event-log').textContent=JSON.stringify(state.events.slice(-15).reverse(),null,2);$('#raw-live').textContent=JSON.stringify(state,null,2);}
function ownQuestions(){return state.questions.filter(q=>q.canonical_participant_id===state.active_participant_id);}
function render(){
  const p=model.participant(state);let content='';
  const mode=page==='queue'?'reviewer':page==='dashboard'?'measurement':'participant';
  const signpost=$('#mode-indicator');signpost.dataset.mode=mode;
  signpost.textContent=mode==='reviewer'?'Reviewer mode · Synthetic decisions and operational follow-up':mode==='measurement'?'Measurement mode · Synthetic snapshot and separate live QA':'Participant mode · Disclosure, questions and optional acknowledgement';
  document.querySelectorAll('.tabs [data-action]').forEach(button=>{if(button.dataset.action===({participant:'journey',reviewer:'queue',measurement:'dashboard'})[mode])button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');});
  if(page==='join')content=`<article class="panel hero"><span class="eyebrow">SUNCREST PROTOCOL · FICTIONAL COMMUNITY REVIEW</span><h1>Turn a disclosure view into a useful question.</h1><p class="lead">Community Review Now Open. Choose a synthetic participant to explore disclosure, questions, review and follow-up. A wallet and KYC are optional.</p><div class="notice">This is a local synthetic experiment. No real person, email, identity document, signature or fee is used. Reset/reload clears all live actions.</div><label for="persona">Synthetic registration alias</label><select id="persona"><option value="john-primary">John Doe · approved · not KYC verified</option><option value="john-returning-alias">John Doe · duplicate/returning alias</option><option value="maya-primary">Maya · approved · KYC verified</option><option value="avery-primary">Avery · different person on this same browser</option><option value="sam-waiting">Sam · waiting / ineligible</option></select><div class="actions"><button class="button" data-action="register">Join waitlist / continue</button></div><p class="small">Aliases resolve to canonical fixture identities. They do not prove real-world uniqueness or perform bot detection.</p></article>`;
  if(page==='eligibility')content=panel(`<span class="eyebrow">INVITATION ELIGIBILITY</span><h1>${p.eligible?`You're eligible to participate, ${esc(p.persona_label)}!`:'You’re on the synthetic waitlist.'}</h1><p>Canonical identity: <strong>${p.canonical_participant_id}</strong> · Invitation: ${p.invitation_status} · KYC: ${p.kyc_demo_status}.</p>${ownQuestions().length?`<p>Welcome back. You have ${ownQuestions().length} saved question(s). Registration aliases never create another person.</p>`:''}<p>${p.eligible?'Review the disclosure, submit a specific question and optionally explore acknowledgement after saving. Review and qualification never require a wallet or KYC.':"Your invitation is still pending. You're welcome to read the project disclosure, but question submission will become available only after your invitation is approved."}</p><div class="notice">Eligibility is a fixed synthetic fixture, separate from KYC. ${p.eligible?'Approved invitation confirmed.':'You can inspect the disclosure, but this waiting fixture cannot submit or count toward eligible conversion.'}</div><div class="actions"><button class="button" data-action="disclosure">Review Project Disclosure</button><button class="button secondary" data-action="switch">Choose another fixture</button></div>${ownQuestions().length?'<h2>Your saved questions</h2>'+ownQuestions().map(q=>`<p><button class="button text-action" data-action="show-question" data-id="${q.question_id}">${q.question_id} · ${esc(label(q.review_status))}</button></p>`).join(''):''}`);
  if(page==='disclosure')content=panel(`<span class="eyebrow">PUBLIC PROJECT DISCLOSURE · FICTIONAL V1</span><h1>Suncrest Protocol — Public Project Disclosure</h1><p class="lead">A proposed registry for community-reported renewable-energy updates. All claims below are invented for this exercise.</p><div class="section-grid">${model.SECTIONS.map(s=>`<section id="section-${s.id}"><span class="eyebrow">${s.id}</span><h3>${s.title}</h3><p>${s.text}</p></section>`).join('')}</div><div class="notice warning">No verified assets, independent audit, reserve evidence, confirmed delivery schedule or guaranteed returns exist. An acknowledgement validates neither ownership nor disclosure accuracy. Opening this page is a view, not evidence of reading or comprehension.</div>${p.eligible?'':'<p id="invitation-help" class="notice">Question submission is available after invitation approval.</p>'}<div class="actions"><button class="button" data-action="question" ${p.eligible?'':'disabled aria-describedby="invitation-help"'}>${state.drafts[p.canonical_participant_id]?.text?'Return to your draft':'Ask a specific question'}</button><button class="button secondary" data-action="abandon">Exit without submission · discard draft</button></div>`);
  if(page==='question'){const draft=state.drafts[p.canonical_participant_id]||{text:'',section_id:''};content=panel(`<span class="eyebrow">${editingId?'CLARIFY '+editingId:'OFF-CHAIN CONTRIBUTION'}</span><h1>What would you like clarified?</h1><p>Ask for specific evidence, an explanation or investigable follow-up about a claim, assumption, risk or gap. Critical questions are welcome. No minimum word count or supportive tone is required.</p><form id="question-form" novalidate><label for="section">Referenced disclosure section</label><select id="section">${sectionOptions(draft.section_id)}</select><label for="question-text">Your question</label><textarea id="question-text" maxlength="2000" aria-describedby="question-help question-error">${esc(draft.text)}</textarea><p class="small" id="question-help">Synthetic content only. Maximum 2,000 UTF-16 units. Draft stays when you go back; explicit exit discards it. Submitted does not mean qualified.</p><p class="error" id="question-error" role="alert"></p><div class="actions"><button class="button" type="submit">${editingId?'Save clarification':'Submit question'}</button><button class="button secondary" type="button" data-action="back">Back to disclosure</button><button class="button text-action" type="button" data-action="abandon">Exit and discard draft</button></div></form>`);}
  if(page==='saved')content=panel(`<span class="eyebrow">SAVED BEFORE ANY WALLET DECISION</span><h1>Question ${currentId} is saved.</h1>${preview(qCurrent())}<p>Your submission remains available for review regardless of the wallet outcome.</p>`);
  if(page==='confirmation'){const q=qCurrent();content=panel(`<span class="eyebrow">QUESTION ${q.question_id} · VERSION ${q.version}</span><h1>Your question is saved.</h1>${preview(q)}<div class="notice"><strong>${esc(ackLabel(q))}</strong><br>No real signature, blockchain transaction, TXID or fee occurred.</div><p><span class="badge">Review: ${esc(label(q.review_status))}</span> <span class="badge">Follow-up: ${esc(label(q.followup_status))}</span></p><p class="small">${esc(q.review_reason?.reason_note||'Pending a synthetic reviewer decision; not yet qualified.')} ${esc(q.next_action)}</p>${q.similar_to?.length?`<p class="small">Possible wording overlap with ${q.similar_to.join(', ')}. Flag for review only; this is not automatic rejection or qualification.</p>`:''}${model.canRetry(q)?'<div class="actions"><button class="button secondary" data-action="retry">Retry acknowledgement</button><button class="button text-action" data-action="offchain">Continue off-chain</button></div>':''}${q.review_status==='needs_clarification'?'<button class="button secondary" data-action="revise">Clarify this question</button>':''}<h2>Would you like to submit another question?</h2><div class="actions"><button class="button" data-action="another">Yes, submit another question</button><button class="button secondary" data-action="done">No, I’m done</button><button class="button text-action" data-action="queue">Open reviewer queue</button></div>${certificateButtons([q])}`);}
  if(page==='done')content=panel(`<span class="eyebrow">PARTICIPATION COMPLETE</span><h1>Thank you for participating, ${esc(p.persona_label)}!</h1><p>${ownQuestions().length} saved question(s). Current review and follow-up remain visible in the reviewer queue. Returning registration keeps the canonical identity in this tab.</p><div class="actions"><button class="button" data-action="switch">Return / switch persona</button><button class="button secondary" data-action="queue">Review saved questions</button></div>${certificateButtons(ownQuestions())}`);
  if(page==='queue')content=reviewQueue();
  if(page==='dashboard')content=dashboard();
  $('#main').innerHTML=content;notebook();if(!modalOpen)$('#main').focus();
}
function reviewQueue(){
  if(!state.questions.length)return panel('<span class="eyebrow">SYNTHETIC REVIEWER</span><h1>No saved questions yet.</h1><p>Complete a wallet-free submission in the participant journey first. The experiment snapshot is separate and cannot be changed here.</p>');
  const q=state.questions.find(q=>q.question_id===queueId)||state.questions.at(-1);queueId=q.question_id;
  return panel(`<span class="eyebrow">REVIEWER-CONTROLLED · NO AI GRADING</span><h1>Review the question, not its sentiment.</h1><p>Qualification requires an eligible viewer, a referenced material topic, an actionable inquiry and no spam/duplicate/abuse. A short critical question can qualify. Wallet/KYC status is irrelevant.</p><label for="review-question">Saved question</label><select id="review-question">${state.questions.map(x=>`<option value="${x.question_id}" ${q===x?'selected':''}>${x.question_id} · ${x.canonical_participant_id} · ${esc(label(x.review_status))}</option>`).join('')}</select><div class="queue-card"><span class="badge">${q.disclosure_section_id} · v${q.version}</span>${preview(q)}<p class="small">${esc(ackLabel(q))}</p><p class="small">Current follow-up: ${esc(q.followup_owner)} · ${esc(label(q.followup_status))} · ${esc(q.next_action)}</p></div><form id="review-form" data-id="${q.question_id}">${reviewFields(q)}</form>${q.review_status==='qualified'?`<form id="followup-form" data-id="${q.question_id}"><h2>Operational follow-up</h2><label for="followup-status">Follow-up status</label><select id="followup-status">${['unassigned','triaged','response_pending','addressed'].map(s=>`<option value="${s}" ${q.followup_status===s?'selected':''}>${esc(label(s))}</option>`).join('')}</select><label for="followup-owner">Synthetic owner</label><select id="followup-owner"><option value="" ${q.followup_owner==='Unassigned'?'selected':''}>Choose a synthetic owner</option>${['Synthetic operations reviewer','Synthetic engineering reviewer'].map(owner=>`<option ${q.followup_owner===owner?'selected':''}>${owner}</option>`).join('')}</select><label for="next-action">Next action</label><input id="next-action" maxlength="300" value="${esc(q.next_action)}"><p class="small">Any response/SLA is simulated; no business action or real reply is asserted.</p><button class="button secondary" type="submit">Save follow-up</button></form>`:''}<details><summary>Technical Evidence · Canonical review, revision and acknowledgement history</summary><pre>${esc(JSON.stringify({review_history:q.review_history,revisions:q.revisions,attempts:state.ack_attempts.filter(a=>a.question_id===q.question_id)},null,2))}</pre></details><button class="button text-action" data-action="show-current">Return to active participant’s last question</button>`);
}
function dashboard(){const c=compare(snapshot),live=metrics(state,{includeQA:true});return panel(`<span class="eyebrow">IMMUTABLE SYNTHETIC EXPERIMENT SNAPSHOT</span><h1>Qualified contribution is the outcome.</h1><p>Illustrative email fixtures only. These are not observed users, forecasts, causal estimates or statistically significant findings. Live clicks below never change this snapshot.</p><section class="variant-guide" aria-labelledby="variants-title"><h2 id="variants-title">Synthetic, unsent email variants</h2><p><strong>Control:</strong> Generic invitation to review the disclosure and ask a question.</p><p><strong>Variant:</strong> Invitation emphasizes asking a specific question and seeing review status / next action.</p><p class="small">Both use the same disclosure and wallet/KYC policy. No email was sent; these fixtures do not establish a causal winner.</p></section>${funnelMarkup('Snapshot funnel · pooled synthetic records',c.pooled)}<div class="metric-grid"><div class="metric"><strong>${format(c.control.qualified_conversion)}</strong><span>Control · ${c.control.qualified_participants}/${c.control.disclosure_viewers} qualified viewers</span></div><div class="metric"><strong>${format(c.variant.qualified_conversion)}</strong><span>Variant · ${c.variant.qualified_participants}/${c.variant.disclosure_viewers} qualified viewers</span></div><div class="metric"><strong>${format(c.pooled.qualified_conversion)}</strong><span>Pooled · ${c.pooled.qualified_participants}/${c.pooled.disclosure_viewers}</span></div><div class="metric"><strong>+${c.absolute_pp}pp</strong><span>Absolute illustration</span></div><div class="metric"><strong>+${format(c.relative_improvement)}</strong><span>Relative illustration</span></div><div class="metric"><strong>${c.pooled.real_transactions}</strong><span>Real blockchain transactions</span></div></div><div class="table-wrap"><table><caption>Derived from canonical records, same cohort and time window</caption><thead><tr><th>Metric</th><th>Control</th><th>Variant</th><th>Pooled</th></tr></thead><tbody>${[['Invitations','invited'],['Eligible disclosure viewers','disclosure_viewers'],['Question submitters','question_submitters'],['Accepted questions','accepted_questions'],['Qualified questions','qualified_questions'],['Qualified participants','qualified_participants'],['Pending review','pending_questions'],['Needs clarification','clarification_questions'],['Excluded questions','excluded_questions'],['Invitation → qualified %','invitation_to_qualified'],['Question qualification %','question_qualification_rate'],['Duplicate registration attempts','duplicate_registration_attempts'],['Demo acknowledgement attempts','ack_attempts'],['Demo successes','ack_successes'],['Sponsored successes','sponsored_successes']].map(([label,key])=>`<tr><td>${label}</td>${[c.control,c.variant,c.pooled].map(x=>`<td>${key.endsWith('rate')||key==='invitation_to_qualified'?format(x[key]):x[key]}</td>`).join('')}</tr>`).join('')}</tbody></table></div><details class="technical-evidence"><summary>Technical Evidence</summary><h3>Snapshot calculations and raw fixture links</h3><pre>${esc(JSON.stringify(c,null,2))}</pre><p><a href="../data/experiment.synthetic.json">Full JSON</a> · <a href="../data/participants.synthetic.csv">Participants CSV</a> · <a href="../data/questions.synthetic.csv">Questions CSV</a> · <a href="../measurement/README.md">Formulas / exclusions</a></p></details><div class="notice">Formula: distinct eligible canonical disclosure viewers with ≥1 currently qualified question / distinct eligible canonical disclosure viewers. Repeated aliases, repeated opens and multiple qualified questions do not add people. QA fixtures are excluded. Submission, qualification, demo acknowledgements and real transactions are separate.</div><section class="live-qa" aria-labelledby="live-title"><h2 id="live-title">Live QA sandbox · separate records</h2><div class="notice warning"><strong>Tiny synthetic sample — not an experiment result.</strong> Even 100% live QA conversion may mean only one qualified person out of one eligible viewer. It is not evidence of real-user value, causal lift or statistical significance. Live invitations are preconfigured eligible fixtures, not sent emails.</div>${funnelMarkup('Live QA funnel · separate synthetic records',live)}<p>Qualified conversion ${format(live.qualified_conversion)} = ${live.qualified_participants}/${live.disclosure_viewers}; ${live.accepted_questions} accepted questions, ${live.qualified_questions} qualified questions; ${live.ack_attempts} demo attempts; ${live.real_transactions} real transactions. Zero denominator is N/A.</p><details class="technical-evidence"><summary>Technical Evidence</summary><h3>Live QA calculation output</h3><pre>${esc(JSON.stringify(live,null,2))}</pre></details></section>`);}
function rememberAckScenario(){
  const scenario=ackScenario(ackScenarios,qCurrent());
  scenario.connect=$('#connect-outcome').value;scenario.ack=$('#ack-outcome').value;scenario.expanded=$('#ack-scenarios').open;
}
function renderAck(){
  const q=qCurrent(),p=model.participant(state),connected=state.wallet_connections.includes(p.canonical_participant_id),scenario=ackScenario(ackScenarios,q);
  $('#ack').innerHTML='<button class="close" data-action="dismiss" aria-label="Close and continue off-chain">×</button><span class="eyebrow">OPTIONAL ACKNOWLEDGEMENT · LOCAL DEMO</span><h2 id="ack-title">Question '+q.question_id+' is already saved.</h2><p>A real acknowledgement could give an independently verifiable receipt; it would not validate the question, assets, reserves, ownership or returns. Qualification is a separate review.</p><div class="notice">'+sponsorshipMarkup(model.gasPolicy(state,q.question_id))+'</div>'+(connectionError?'<p class="notice error" role="alert">Demo connection failed. Your question is still saved. Try again or continue off-chain.</p>':'')+'<details id="ack-scenarios"'+(scenario.expanded?' open':'')+'><summary>Reviewer test scenarios</summary><label for="connect-outcome">Connection outcome</label><select id="connect-outcome">'+outcomeOptions(scenario.connect)+'</select><label for="ack-outcome">Acknowledgement outcome</label><select id="ack-outcome">'+outcomeOptions(scenario.ack)+'</select></details><p class="small">'+(connected?'Demo wallet remains connected. ':'')+'No real signature, payment, blockchain transaction or TXID will occur.</p><div class="actions"><button class="button" data-action="'+(connected?'acknowledge':'connect')+'">'+(connected?'Record demo acknowledgement':'Connect Wallet')+'</button><button class="button text-action" data-action="offchain">Continue off-chain</button></div>';
}
function openAck(){modalOpen=true;connectionError=false;renderAck();$('#ack').showModal();}
function closeAck(){modalOpen=false;if($('#ack').open)$('#ack').close();}
function offchain(source){model.continueOffchain(state,currentId,source);closeAck();page='confirmation';render();}
const actions={
  register(){const r=model.register(state,$('#persona').value);page='eligibility';editingId=null;currentId=null;notify(r.duplicate_resolution==='existing_canonical'?'Returning alias resolved to the same canonical participant.':'Synthetic waitlist registration saved.');render();},
  switch(){page='join';render();},journey(){page=state.active_participant_id?'eligibility':'join';render();},
  disclosure(){model.openDisclosure(state);page='disclosure';render();},
  question(){model.beginQuestion(state);page='question';render();$('#question-text').focus();},back(){model.openDisclosure(state,true);page='disclosure';render();},
  abandon(){model.abandon(state);editingId=null;page='eligibility';render();},
  another(){model.beginQuestion(state);editingId=null;currentId=null;page='question';render();$('#question-text').focus();},
  done(){model.completeSession(state);page='done';render();},
  queue(){page='queue';render();},dashboard(){page='dashboard';render();},
  connect(){rememberAckScenario();connectionError=!model.connectWallet(state,currentId,ackScenario(ackScenarios,qCurrent()).connect);renderAck();notebook();},
  acknowledge(){rememberAckScenario();model.acknowledge(state,currentId,ackScenario(ackScenarios,qCurrent()).ack);closeAck();page='confirmation';render();},
  retry(){model.retryAcknowledgement(state,currentId);page='saved';render();openAck();},
  offchain(){offchain('continue_off_chain');},dismiss(){offchain('dismiss_button');},
  revise(){const q=qCurrent();editingId=q.question_id;model.saveDraft(state,q.text,q.disclosure_section_id);page='question';render();},
  'show-question'(id){const q=ownQuestions().find(q=>q.question_id===id);if(!q)throw Error('Select the owner of this question.');currentId=id;editingId=null;page='confirmation';render();},
  'show-current'(){const q=ownQuestions().at(-1);if(q){currentId=q.question_id;page='confirmation';}else page='eligibility';render();},
  certificate(id){const c=model.certificateRecord(state,id);$('#certificate-content').innerHTML=certificateMarkup(c);$('#certificate').showModal();}
};
document.addEventListener('click',event=>{const b=event.target.closest('[data-action]');if(!b)return;notify('');try{actions[b.dataset.action]?.(b.dataset.id);}catch(error){notify(error.message);}});
$('#brand').addEventListener('click',event=>{event.preventDefault();actions.journey();});
$('#main').addEventListener('input',event=>{if(page==='question'&&['question-text','section'].includes(event.target.id)){model.saveDraft(state,$('#question-text').value,$('#section').value);$('#question-error').textContent='';}});
$('#main').addEventListener('change',event=>{
  if(event.target.id==='review-question'){queueId=event.target.value;render();}
  if(event.target.id==='review-status'){
    $('#review-reason').innerHTML=reasonOptions(event.target.value,$('#review-reason').value);
    $('#qualification-checklist').hidden=event.target.value!=='qualified';
  }
});
$('#ack').addEventListener('change',event=>{if(['connect-outcome','ack-outcome'].includes(event.target.id))rememberAckScenario();});
$('#main').addEventListener('submit',event=>{event.preventDefault();notify('');try{
  if(event.target.id==='question-form'){const result=editingId?model.reviseQuestion(state,editingId,$('#question-text').value,$('#section').value):model.submitQuestion(state,$('#question-text').value,$('#section').value);if(!result.ok){$('#question-error').textContent=result.message;notebook();return;}currentId=result.question.question_id;editingId=null;page='saved';render();openAck();}
  if(event.target.id==='review-form'){model.reviewQuestion(state,event.target.dataset.id,{decision:$('#review-status').value,reason_code:$('#review-reason').value,reason_note:$('#review-note').value,criteria:$('#review-status').value==='qualified'?{material:$('#material').checked,actionable:$('#actionable').checked,not_spam:$('#not-spam').checked}:{}});notify('Synthetic review saved. Conversion now uses current adjudication.');render();}
  if(event.target.id==='followup-form'){model.setFollowup(state,event.target.dataset.id,{status:$('#followup-status').value,owner:$('#followup-owner').value,next_action:$('#next-action').value});notify('Simulated operational follow-up saved.');render();}
}catch(error){notify(error.message);}});
$('#ack').addEventListener('cancel',event=>{event.preventDefault();offchain('escape_dismissal');});$('#ack').addEventListener('close',()=>{if(modalOpen)offchain('dialog_dismissal');});
$('#close-certificate').addEventListener('click',()=>$('#certificate').close());$('#print-certificate').addEventListener('click',()=>window.print());
$('#reset').addEventListener('click',()=>{closeAck();if($('#certificate').open)$('#certificate').close();state=model.createSession();ackScenarios.clear();page='join';currentId=null;editingId=null;queueId=null;notify('Live sandbox reset. Experiment snapshot unchanged.');render();});
try{const response=await fetch('../data/experiment.synthetic.json');if(!response.ok)throw Error('Cannot load local experiment fixture. Start the documented server.');snapshot=await response.json();render();}catch(error){$('#main').textContent=error.message;}
